package main

import (
	"fmt"
	"os"
)

const version = "v1.13.0"

const helpText = "\n  walk v1.13.0\n\n  Usage: walk [path]\n\n    arrows, hjkl  Move cursor\n    enter         Enter directory\n    backspace     Exit directory\n    space         Toggle preview\n    esc, q        Exit with cd\n    ctrl+c        Exit without cd\n    /             Fuzzy search\n    d, delete     Delete file or dir\n    y             Copy to clipboard\n    .             Hide hidden files\n    ?             Show help\n\n  Flags:\n\n    --icons        display icons\n    --dir-only     show dirs only\n    --hide-hidden  hide hidden files\n    --preview      display preview\n    --with-border  preview with border\n    --fuzzy        fuzzy mode\n\n"

func main() {
	args := os.Args[1:]
	// Check for help/version in order, with -h/-v only valid at index 0
	for i, a := range args {
		if a == "--help" || (a == "-h" && i == 0) {
			fmt.Fprint(os.Stderr, helpText)
			os.Exit(1)
		}
		if a == "--version" || (a == "-v" && i == 0) {
			fmt.Fprintln(os.Stdout, version)
			os.Exit(0)
		}
		// Note: need to handle order correctly: first help/version in order wins
		// Our loop does that: first valid help/version encountered triggers.
		// But what about -h at index 1 (invalid) vs --version at index 2? We skip invalid -h, then trigger version. Good.
		// However, our current code checks help then version per arg, so for arg "--help" it triggers help, for "--version" triggers version.
		// For order "--help --version", i0 is --help -> help. Good. For "--version --help", i0 is --version -> version. Good.
		// But what about "-h --version"? i0 is -h (valid, since i==0) -> help. Good.
		// What about "--version -h"? i0 is --version -> version. Good (even though -h at i1 is invalid anyway).
		// Actually our code checks both help and version for each arg, but for "-h" at i1, first condition fails (since i!=0), second condition checks version (fails), so continues. Good.
	}
	// Parse flags and path
	var showIcons, dirOnly, hideHidden, preview, withBorder, fuzzy bool
	var path string
	pathSet := false
	for _, a := range args {
		switch a {
		case "--icons":
			showIcons = true
		case "--dir-only":
			dirOnly = true
		case "--hide-hidden":
			hideHidden = true
		case "--preview":
			preview = true
		case "--with-border":
			withBorder = true
		case "--fuzzy":
			fuzzy = true
		default:
			if !pathSet {
				path = a
				pathSet = true
			}
		}
	}
	_ = showIcons
	_ = dirOnly
	_ = hideHidden
	_ = preview
	_ = withBorder
	_ = fuzzy
	_ = path
	// Try to open TTY
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		panic("could not open a new TTY: " + err.Error())
	}
	tty.Close()
	fmt.Fprintln(os.Stderr, "TUI not implemented yet")
	os.Exit(2)
}
