package main

import (
	"fmt"
	"os"
)

// fileInfo returns os.FileInfo for path using Lstat (does not follow symlinks for Size/Mode? Actually for Size/Mode we need Lstat)
func fileInfo(path string) os.FileInfo {
	fi, err := os.Lstat(path)
	if err != nil {
		panic(err.Error())
	}
	return fi
}

func formatSize(size int64) string {
	if size < 1024 {
		return fmt.Sprintf("%dB", size)
	} else if size < 1024*1024 {
		return fmt.Sprintf("%.1fKB", float64(size)/1024)
	} else if size < 1024*1024*1024 {
		return fmt.Sprintf("%.1fMB", float64(size)/1024/1024)
	} else if size < 1024*1024*1024*1024 {
		return fmt.Sprintf("%.1fGB", float64(size)/1024/1024/1024)
	} else {
		return fmt.Sprintf("%.1fTB", float64(size)/1024/1024/1024/1024)
	}
}
GOEOF
cat /workspace/utils.go
"}

