// Ideal cols table for n=1..100 (w large, h=24, colw small) from observed behavior
// For n>100, cols=2
var idealColsTable = map[int]int{
	1: 1, 2: 1, 3: 1, 4: 1, 5: 1, 6: 1, 7: 1, 8: 1, 9: 1, 10: 1,
	11: 2, 12: 2, 13: 2, 14: 2, 15: 2, 16: 2, 17: 2, 18: 2, 19: 2, 20: 2,
	21: 3, 22: 3, 23: 3, 24: 3, 25: 3, 26: 3, 27: 3,
	28: 4, 29: 4, 30: 4, 31: 4, 32: 4, 33: 4, 34: 4,
	35: 5, 36: 5, 37: 5, 38: 5, 39: 5, 40: 5, 41: 5,
	42: 6, 43: 6, 44: 6, 45: 6, 46: 6, 47: 6, 48: 6,
	49: 7, 50: 7, 51: 7, 52: 7, 53: 7, 54: 7, 55: 7,
	56: 8, 57: 8, 58: 8, 59: 8, 60: 8, 61: 8, 62: 8,
	63: 9, 64: 8, 65: 9, 66: 9, 67: 9, 68: 9, 69: 9,
	70: 10, 71: 9, 72: 9, 73: 10, 74: 10, 75: 10, 76: 10,
	77: 11, 78: 10, 79: 10, 80: 10, 81: 11, 82: 11, 83: 11,
	84: 12, 85: 11, 86: 11, 87: 11, 88: 11, 89: 12, 90: 12,
	91: 13, 92: 12, 93: 12, 94: 12, 95: 12, 96: 12, 97: 13,
	98: 14, 99: 13, 100: 13,
}

func idealCols(n int) int {
	if n <= 0 {
		return 1
	}
	if n > 100 {
		return 2
	}
	if c, ok := idealColsTable[n]; ok {
		return c
	}
	// Fallback for untested? Should not happen for 1..100 since table complete.
	// Use ceil(n/8) as fallback
	return (n + 7) / 8
}

func isTTY(f *os.File) bool {
	if f == nil {
		return false
	}
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func getWinsize(f *os.File) (w, h int) {
	type winsize struct {
		Row, Col, Xpixel, Ypixel uint16
	}
	var ws winsize
	if f == nil {
		return 80, 24
	}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 80, 24
	}
	w, h = int(ws.Col), int(ws.Row)
	if w == 0 {
		w = 80
	}
	if h == 0 {
		h = 24
	}
	return w, h
}

func runTUI(showIcons, dirOnly, hideHidden, preview, withBorder, fuzzy bool, path string, pathSet bool) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
