	_ = hideHidden
	_ = preview
	_ = withBorder
	_ = fuzzy
	_ = path
	_ = pathSet
	fmt.Fprintln(os.Stderr, "TUI not implemented yet")
	os.Exit(2)
}

var _ = exec.Command
var _ = filepath.Abs
var _ = sort.Strings
var _ = strings.Contains
var _ = time.Now
