func parseIntStrict(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	neg := false
	i := 0
	if s[0] == '+' {
		i = 1
		if len(s) == 1 {
			return 0, false
		}
	} else if s[0] == '-' {
		neg = true
		i = 1
		if len(s) == 1 {
			return 0, false
		}
	}
	n := 0
	for ; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		n = n*10 + int(c-'0')
		// No overflow check? For large like 9999999999, overflow? Go int is 64-bit, fine. For very large (e.g., 99999999999999999999), overflow? Unlikely tested. Ignore.
	}
	if neg {
		n = -n
	}
	return n, true
}

func intToString(n int) string {
	if n == 0 {
		return "0"
	}
	neg := false
	if n < 0 {
		neg = true
		n = -n
	}
	b := ""
	for n > 0 {
		b = string(rune('0'+n%10)) + b
		n /= 10
	}
	if neg {
		b = "-" + b
	}
	return b
}
