		for k := 1; k < len(indices); k++ {
			if indices[k] == indices[k-1]+1 {
				consec++
			}
		}
		ln := runeLen(f.name)
		if first {
			bestIdx = i
			bestFirst = firstPos
			bestConsec = consec
			bestLen = ln
			first = false
			continue
		}
		better := false
		if firstPos < bestFirst {
			better = true
		} else if firstPos == bestFirst {
			if consec > bestConsec {
				better = true
			} else if consec == bestConsec {
				if ln < bestLen {
					better = true
				} else if ln == bestLen {
					better = true
				}
			}
		}
		if better {
			bestIdx = i
			bestFirst = firstPos
			bestConsec = consec
			bestLen = ln
		} else if firstPos == bestFirst && consec == bestConsec && ln == bestLen {
			bestIdx = i
		}
	}
	return bestIdx
}
